fn map_optional_node<V: NodeDataChildVisitor>(
    slot: &mut Option<NodeId>,
    visitor: &mut V,
) -> Result<(), V::Error> {
    if let Some(id) = *slot {
        *slot = visitor.visit_node(id)?;
    }
    Ok(())
}

fn map_optional_nodes<V: NodeDataChildVisitor>(
    slot: &mut Option<NodeArrayId>,
    visitor: &mut V,
) -> Result<(), V::Error> {
    if let Some(id) = *slot {
        *slot = visitor.visit_nodes(id)?;
    }
    Ok(())
}

#[allow(dead_code)]
fn map_required_node<V: NodeDataChildVisitor>(
    slot: &mut NodeId,
    parent: SyntaxKind,
    field: &'static str,
    visitor: &mut V,
) -> Result<(), V::Error> {
    *slot = visitor
        .visit_node(*slot)?
        .ok_or_else(|| visitor.required_child_removed(parent, field))?;
    Ok(())
}

#[allow(dead_code)]
fn map_required_nodes<V: NodeDataChildVisitor>(
    slot: &mut NodeArrayId,
    parent: SyntaxKind,
    field: &'static str,
    visitor: &mut V,
) -> Result<(), V::Error> {
    *slot = visitor
        .visit_nodes(*slot)?
        .ok_or_else(|| visitor.required_child_removed(parent, field))?;
    Ok(())
}

fn map_optional_jsdoc_comment<V: NodeDataChildVisitor>(
    slot: &mut Option<JSDocComment>,
    visitor: &mut V,
) -> Result<(), V::Error> {
    let Some(JSDocComment::Nodes(id)) = slot.as_ref() else {
        return Ok(());
    };
    *slot = visitor.visit_nodes(*id)?.map(JSDocComment::Nodes);
    Ok(())
}

#[allow(dead_code)]
fn map_jsdoc_comment<V: NodeDataChildVisitor>(
    slot: &mut JSDocComment,
    parent: SyntaxKind,
    field: &'static str,
    visitor: &mut V,
) -> Result<(), V::Error> {
    if let JSDocComment::Nodes(id) = slot {
        *id = visitor
            .visit_nodes(*id)?
            .ok_or_else(|| visitor.required_child_removed(parent, field))?;
    }
    Ok(())
}

fn visit_node<F>(id: NodeId, cb: &mut F) -> Option<NodeId>
where
    F: FnMut(NodeId) -> bool,
{
    if cb(id) {
        Some(id)
    } else {
        None
    }
}

fn visit_optional_node<F>(id: Option<NodeId>, cb: &mut F) -> Option<NodeId>
where
    F: FnMut(NodeId) -> bool,
{
    id.and_then(|id| visit_node(id, cb))
}

fn visit_nodes<L, F>(lookup: &L, id: NodeArrayId, cb: &mut F) -> Option<NodeId>
where
    L: NodeLookup,
    F: FnMut(NodeId) -> bool,
{
    for node in &lookup.node_array(id).nodes {
        if cb(*node) {
            return Some(*node);
        }
    }
    None
}

fn visit_optional_jsdoc_comment<L, F>(
    lookup: &L,
    comment: Option<&JSDocComment>,
    cb: &mut F,
) -> Option<NodeId>
where
    L: NodeLookup,
    F: FnMut(NodeId) -> bool,
{
    match comment {
        Some(JSDocComment::Nodes(nodes)) => visit_nodes(lookup, *nodes, cb),
        _ => None,
    }
}

fn visit_optional_nodes<L, F>(lookup: &L, id: Option<NodeArrayId>, cb: &mut F) -> Option<NodeId>
where
    L: NodeLookup,
    F: FnMut(NodeId) -> bool,
{
    id.and_then(|id| visit_nodes(lookup, id, cb))
}
